DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC_GUIDE_ETERNALNUMBERTEN' OR Tag GLOB 'TXT_KEY_CWC_GUIDE_ETERNALNUMBERTEN_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ETERNALNUMBERTEN_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ETERNALNUMBERTEN_CIV_TEXT_1','Eternal Number Ten[NEWLINE]Great People, diplomacy and a permanent career progression[NEWLINE]Culture or Diplomacy; Science through specialists[NEWLINE][NEWLINE]Build a reliable stream of defining achievements and keep the career moving through both Legacy and Era gates. Use formation play to support the economy, rather than making every chapter depend on risky fighting.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ETERNALNUMBERTEN_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ETERNALNUMBERTEN_CIV_TEXT_2','Establish food and early Culture, explore for contacts, and prepare cities that can support specialists. Choose achievable Great Person and diplomatic milestones; a chapter requiring a later Era cannot be rushed by Legacy alone.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ETERNALNUMBERTEN_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ETERNALNUMBERTEN_CIV_TEXT_3','Use La Masia in genuine specialist cities and keep the Number Ten protected near coordinated land forces. Position the formation before turn start to receive One-Two Football, and take eligible Assists without exposing the support unit.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ETERNALNUMBERTEN_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ETERNALNUMBERTEN_CIV_TEXT_4','Convert permanent career benefits into Tourism, Great Works and alliances. Bank a coherent route to late chapters instead of pursuing every Wonder. After the final chapter, further Legacy has its own bounded repeat rewards.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ETERNALNUMBERTEN_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ETERNALNUMBERTEN_CIV_TEXT_5','- Several peaceful and military achievements contribute to one permanent progression.[NEWLINE]- La Masia supports specialists, Great People and local growth.[NEWLINE]- Formation bonuses and the Number Ten improve tactical positioning.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ETERNALNUMBERTEN_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ETERNALNUMBERTEN_CIV_TEXT_6','- Later chapters need specific Eras as well as sufficient Legacy.[NEWLINE]- Great People, Wonders and alliances compete with ordinary economic needs.[NEWLINE]- Formation and Assist rewards require real positioning and eligibility.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ETERNALNUMBERTEN_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ETERNALNUMBERTEN_CIV_TEXT_7','- Contest accessible Wonder and City-State opportunities without feeding easy Assists.[NEWLINE]- Use pressure that forces the specialist cities to divert resources into defense.[NEWLINE]- Separate the support General from the formation and finish exposed units decisively.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ETERNALNUMBERTEN_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ETERNALNUMBERTEN_CIV_TEXT_8','- Expecting banked Legacy to bypass an Era gate.[NEWLINE]- Leaving the Number Ten exposed because its movement is excellent.[NEWLINE]- Treating every nominal kill as an eligible Assist or unlimited reward source.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ETERNALNUMBERTEN_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ETERNALNUMBERTEN_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Substitute Classroom: Permanent career benefits can support a steady long game through the gaps between Garvey''s temporary choices.[NEWLINE][NEWLINE]The Conical Union: Specialists, alliances and career progression offer a route beyond a contest over flat connection yields, if the empire remains safe.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Viltrum: A decisive city-conquest campaign can dismantle the protected specialist and diplomatic base before the later chapters matter.[NEWLINE][NEWLINE]The Filthy Realm: Persistent foreign-city disruption makes a concentrated cultural economy and its timing more difficult to protect.');
