INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ETERNALNUMBERTEN_LEADER_BACKGROUND','Build a reliable stream of defining achievements and keep the career moving through both Legacy and Era gates. Use formation play to support the economy, rather than making every chapter depend on risky fighting.');
