INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ETERNALNUMBERTEN_STRATEGY','Build a reliable stream of defining achievements and keep the career moving through both Legacy and Era gates. Use formation play to support the economy, rather than making every chapter depend on risky fighting.[NEWLINE][NEWLINE]Establish food and early Culture, explore for contacts, and prepare cities that can support specialists. Choose achievable Great Person and diplomatic milestones; a chapter requiring a later Era cannot be rushed by Legacy alone.[NEWLINE][NEWLINE]Use La Masia in genuine specialist cities and keep the Number Ten protected near coordinated land forces. Position the formation before turn start to receive One-Two Football, and take eligible Assists without exposing the support unit.[NEWLINE][NEWLINE]Convert permanent career benefits into Tourism, Great Works and alliances. Bank a coherent route to late chapters instead of pursuing every Wonder. After the final chapter, further Legacy has its own bounded repeat rewards.');
