INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ETERNALNUMBERTEN_LEADER_TEXT_2','Establish food and early Culture, explore for contacts, and prepare cities that can support specialists. Choose achievable Great Person and diplomatic milestones; a chapter requiring a later Era cannot be rushed by Legacy alone.[NEWLINE][NEWLINE]Use La Masia in genuine specialist cities and keep the Number Ten protected near coordinated land forces. Position the formation before turn start to receive One-Two Football, and take eligible Assists without exposing the support unit.[NEWLINE][NEWLINE]Convert permanent career benefits into Tourism, Great Works and alliances. Bank a coherent route to late chapters instead of pursuing every Wonder. After the final chapter, further Legacy has its own bounded repeat rewards.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ETERNALNUMBERTEN_LEADER_HEADING_3','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ETERNALNUMBERTEN_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Substitute Classroom: Permanent career benefits can support a steady long game through the gaps between Garvey''s temporary choices.[NEWLINE][NEWLINE]The Conical Union: Specialists, alliances and career progression offer a route beyond a contest over flat connection yields, if the empire remains safe.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Viltrum: A decisive city-conquest campaign can dismantle the protected specialist and diplomatic base before the later chapters matter.[NEWLINE][NEWLINE]The Filthy Realm: Persistent foreign-city disruption makes a concentrated cultural economy and its timing more difficult to protect.');
